#!/usr/bin/env bash
# =============================================================================
#  apply-everything.sh · EcoWoods — Floor Collection (master installer)
# -----------------------------------------------------------------------------
#  ONE command. Reproduces the whole feature set on any checkout, idempotently:
#    • 12-product floor collection data (6 species x 2 formats)
#    • 36 images (room / grain / lived-in) from public/gallery.zip
#    • Swipeable card DECK (Tinder/Bumble-style, Pointer Events + CSS transforms,
#      NO external library) with tap-to-open 3-photo + spec lightbox
#    • Native "Book your free in-home estimate" CTA
#    • Page wiring: renders <FloorCatalog/> in #gallery, on-brand section copy
#    • Section reorder so DOM matches the nav (Services > Species > Gallery > ...)
#    • Cleanup: removes the dead PortfolioGallery import + galleryItems + type
#
#  USAGE (from repo root):
#     bash apply-everything.sh
#     pnpm --filter web dev        # then open the *.app.github.dev URL, /#gallery
# =============================================================================
set -euo pipefail
[[ -f pnpm-workspace.yaml && -d apps/web ]] || { echo "X  Run from the repo root."; exit 1; }
WEB=apps/web; APP=$WEB/app
echo ">> EcoWoods — installing the Floor Collection"

# ---- 1. images -------------------------------------------------------------
mkdir -p "$WEB/public/gallery"
have=$(find "$WEB/public/gallery" -name '*.webp' 2>/dev/null | wc -l | tr -d ' ')
if [[ "$have" -lt 36 && -f public/gallery.zip ]]; then
  echo ">> Extracting images from public/gallery.zip"
  t=$(mktemp -d); unzip -o -q public/gallery.zip -d "$t"
  find "$t" -path '*__MACOSX*' -prune -o -name '*.webp' -exec cp {} "$WEB/public/gallery/" \; ; rm -rf "$t"
  have=$(find "$WEB/public/gallery" -name '*.webp' | wc -l | tr -d ' ')
fi
echo "   -> $have webp images present"
[[ "$have" -lt 36 ]] && echo "   !  expected 36 — ensure public/gallery.zip is committed on this branch"

# ---- 2. data + component + css (exact bytes) -------------------------------
mkdir -p "$APP/data" "$APP/components"
echo ">> Writing data/floors.ts"
base64 -d > "$APP/data/floors.ts" <<'B64_FLOORS'

B64_FLOORS
echo ">> Writing components/FloorCatalog.tsx (swipe deck)"
base64 -d > "$APP/components/FloorCatalog.tsx" <<'B64_COMP'

B64_COMP
echo ">> Writing catalog + deck CSS"
CT=$(mktemp); base64 -d > "$CT" <<'B64_CSS'

B64_CSS
node - "$APP/globals.css" "$CT" <<'NODE'
const fs=require('fs'); const [g,c]=process.argv.slice(2);
let s=fs.readFileSync(g,'utf8'); const block=fs.readFileSync(c,'utf8').trim();
s=s.replace(/\n?\/\* === EW:FLOOR-CATALOG-CTA START === \*\/[\s\S]*?\/\* === EW:FLOOR-CATALOG-CTA END === \*\/\n?/g,'\n');
if(s.includes('/* === EW:FLOOR-CATALOG START === */'))
  s=s.replace(/\/\* === EW:FLOOR-CATALOG START === \*\/[\s\S]*?\/\* === EW:FLOOR-CATALOG END === \*\//, block);
else { if(!s.endsWith('\n')) s+='\n'; s+='\n'+block+'\n'; }
fs.writeFileSync(g,s); console.log('   -> deck CSS in place:', s.includes('.fc-stack'));
NODE
rm -f "$CT"

# ---- 3. page.tsx: wiring + copy + reorder + cleanup (all idempotent) --------
echo ">> Wiring page.tsx (render, copy, reorder, cleanup)"
node - "$APP/page.tsx" <<'NODE'
const fs=require('fs'); const p=process.argv[2]; let s=fs.readFileSync(p,'utf8');
// a. FloorCatalog import
if(!s.includes("import FloorCatalog")){
  const imp="import PortfolioGallery from './components/PortfolioGallery';";
  s = s.includes(imp) ? s.replace(imp, imp+"\nimport FloorCatalog from './components/FloorCatalog';")
                      : "import FloorCatalog from './components/FloorCatalog';\n"+s;
}
// b. render swap
s=s.replace('<PortfolioGallery items={galleryItems} />','<FloorCatalog />');
// c. on-brand section copy
s=s.replace('<span className="eyebrow">The Work</span>','<span className="eyebrow">The Collection</span>');
s=s.replace('Toronto&rsquo;s living rooms, <span className="serif-italic">our portfolio.</span>',
            'Twelve floors, <span className="serif-italic">endless rooms.</span>');
s=s.replace('A curated sample of projects completed across the GTA in the last twelve months.',
            'The species and finishes we install across the GTA — tap any floor to see the grain up close and the room it belongs in.');
// d. cleanup dead code
s=s.replace(/import PortfolioGallery from '\.\/components\/PortfolioGallery';\n/,'');
s=s.replace(/type GalleryItem = \{[\s\S]*?\n\};\n/,'');
s=s.replace(/const galleryItems: GalleryItem\[\] = \[[\s\S]*?\n\];\n/,'');
// e. reorder: SpecsCoverage before #gallery
const line='      <SpecsCoverage species={speciesList} areas={serviceAreas} />';
const gi=s.indexOf('id="gallery"'), si=s.indexOf('<SpecsCoverage');
if(!(si!==-1 && gi!==-1 && si<gi) && s.includes(line)){
  s=s.replace(line+'\n','');
  const anchor='      {/* 5 · RESULTS — curated proof */}';
  const inject='      {/* THE DETAIL — placed here so on-page order matches the nav (Species > Gallery). */}\n'+line+'\n\n';
  if(s.includes(anchor)) s=s.replace(anchor, inject+anchor);
  else s=s.replace('      <section className="section paper-texture" id="gallery">',
                   inject+'      <section className="section paper-texture" id="gallery">');
}
fs.writeFileSync(p,s);
const order=[...s.matchAll(/(<SpecsCoverage|id="(?:services|gallery|process|reviews|faq|quote)")/g)].map(m=>m[0].replace('<SpecsCoverage','species').replace(/id="([a-z]+)"/,'$1'));
console.log('   -> renders FloorCatalog:', s.includes('<FloorCatalog />'));
console.log('   -> dead code removed   :', !s.includes('galleryItems') && !s.includes('type GalleryItem'));
console.log('   -> section order       :', order.join(' > '));
NODE

echo ""
echo "OK  Done. Restart dev and open the *.app.github.dev URL (PORTS tab > 3000):"
echo "      pnpm --filter web dev      ->  /#gallery"
